import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    need = n - k

    def ok(D):
        kept = 1
        cur = 0
        j = 0
        while cur < n - 1:
            if j < cur:
                j = cur
            while j + 1 < n and a[j + 1] - a[cur] <= D:
                j += 1
            if j == cur:
                return False
            cur = j
            kept += 1
            if kept > need:
                return False
        return True

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

